// src/data/textureCatalog.ts
// The textures that REALLY exist in /public/textures.
// `textureManifest.json` is generated by scripts/build-texture-manifest.mjs (package.json: predev / pretest / prebuild) and
// shipped in the bundle. `public/textures/index.json` carries the same list next to the images.
//
// 🔁 SELF-HEALING: if the bundled manifest is empty (a code package was unpacked without the textures, or an older build
// wrote `[]`), the app fetches /textures/index.json once and rebuilds the Workshop Matrix from the folder itself — the 307
// images come back without a rebuild. The script no longer overwrites a good list with an empty one either.
import { useEffect, useState } from 'react';
import manifest from './textureManifest.json';

export interface TextureEntry {
  id: string;
  name: string;
  path: string;
  finish: string;
}

const entryOf = (file: string): TextureEntry => ({
  id: `tex_${file}`,
  name: file.replace(/\.[^.]+$/, ''),
  path: `/textures/${encodeURIComponent(file)}`,
  finish: 'MDF Melamine Matt',
});

const bundled: readonly string[] = Array.isArray(manifest) ? (manifest as string[]) : [];

let files: readonly string[] = bundled;
let catalog: TextureEntry[] = bundled.map(entryOf);
const fileSet = new Set<string>(bundled);
const listeners = new Set<() => void>();

/** The list the bundle shipped with, before any self-heal. */
export const bundledTextureFiles: readonly string[] = bundled;

function setFiles(next: readonly string[]) {
  const cleaned = [...new Set(next.filter((f) => typeof f === 'string' && f.length > 0))].sort();
  if (cleaned.length === files.length && cleaned.every((f, i) => f === files[i])) return;
  files = cleaned;
  catalog = cleaned.map(entryOf);
  fileSet.clear();
  cleaned.forEach((f) => fileSet.add(f));
  listeners.forEach((fn) => fn());
}

/** The files known RIGHT NOW (bundled manifest + anything read from the folder). */
export const textureFiles = (): readonly string[] => files;
/** The Workshop Matrix as it stands: re-read it with `useTextureCatalog()` inside a component. */
export const textureCatalog = (): readonly TextureEntry[] => catalog;

let healing: Promise<number> | null = null;
let healed = false;

/**
 * Read /textures/index.json (written next to the images by scripts/build-texture-manifest.mjs). Resolves with how many files
 * the list has afterwards. Safe to call often: it asks the network once unless `force` is set.
 */
export async function healTextureCatalog(force = false): Promise<number> {
  if (!force && (healed || healing)) return healing ?? files.length;
  healed = true;
  healing = (async () => {
    try {
      const res = await fetch(`/textures/index.json?ts=${Date.now()}`, { cache: 'no-store' });
      if (!res.ok) return files.length;
      const data = (await res.json()) as unknown;
      if (Array.isArray(data) && data.length > 0) setFiles([...files, ...(data as string[])]);
    } catch {
      // no index.json (a bundle without the textures): the manifest we have is all there is
    }
    return files.length;
  })();
  const n = await healing;
  healing = null;
  return n;
}

/** The list, live. Every component that draws the matrix uses this, so a heal re-renders it. */
export function useTextureCatalog(): { entries: TextureEntry[]; count: number; reload: () => Promise<number> } {
  const [entries, setEntries] = useState<TextureEntry[]>(catalog);
  useEffect(() => {
    const sync = () => setEntries(catalog);
    listeners.add(sync);
    sync();
    if (!healed) void healTextureCatalog();
    return () => { listeners.delete(sync); };
  }, []);
  return { entries, count: entries.length, reload: () => healTextureCatalog(true) };
}

export const TEXTURE_EXTENSIONS = ['webp', 'jpg', 'jpeg'] as const;

/**
 * `${prefix}${cleanBrand}.{webp|jpg|jpeg}` -> URL path of the first variant that exists in `available`, else null.
 * (The old engine only ever asked for .webp, so wood_agtturkey.jpg / stone_eggeraustria.jpeg could never load.)
 */
export function resolveConventionTexture(
  prefix: string,
  cleanBrand: string,
  available: ReadonlySet<string> = fileSet,
): string | null {
  if (!cleanBrand) return null;
  for (const ext of TEXTURE_EXTENSIONS) {
    const file = `${prefix}${cleanBrand}.${ext}`;
    if (available.has(file)) return `/textures/${encodeURIComponent(file)}`;
  }
  return null;
}
